use super::*;
struct Source{issuer:OriginalSourceTurnIssuer,turn:OriginalSourceTurn}
impl OriginalWorkRecipient for Source{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{self.issuer.validate(&self.turn).map_err(|_|ValueError::invariant("original close fixture Source changed"))}
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(self.turn.identity())}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:OriginalWorkQuote<'reply>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|n|n<=1)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,c:&mut (),check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(c))}
 fn recover_partial<'reply,'turn,'source>(&mut self,c:&mut (),check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(c))}
}
pub(crate) fn with_effect<R>(grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->R)->(R,u128){let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let mut authority=OriginalWorkAuthority::new(Source{issuer,turn});authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut action=None;assert_eq!(work.prepare_for_action(maximum,&mut action).unwrap(),Some(true));let mut receipt=None;work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let result=operation(&mut RetainedAllocationEffect::new(grant,maximum,&mut actual,receipt.as_mut().unwrap()));assert_eq!(actual,None);let performed=OriginalWorkSink::observed_work(receipt.as_ref().unwrap());work.claim_performed_for_action(action,&mut receipt).unwrap();if performed==0{work.cancel_for_action(&mut action).unwrap()}else{let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.take().unwrap().source_refusal().is_none());let mut proof=None;assert!(work.commit_for_action(performed,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}(result,performed)}).unwrap()}
#[test]
fn paid_close_start_matches_the_shared_language_neutral_cases(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️retained-clone/♻️close/🎟️demand/🧪️tests/close-start.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut started=row["started"].as_bool().unwrap();let original=started;let demand=retained_close_start_demand(started);assert_eq!(demand.copy_bytes,usize::from(!started)*std::mem::size_of::<bool>());assert_eq!(retained_close_start_work_demand(started),u64::from(!started));let grant=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,maximum_copy_bytes:row["copy"].as_u64().unwrap()as usize,maximum_depth:row["depth"].as_u64().unwrap()as usize,..Default::default()};let (turn,performed)=with_effect(grant,row["maximumWork"].as_u64().unwrap(),|effect|start_retained_close(&mut started,effect));assert_eq!(turn.work,performed,"flag write must use its original performed receipt");assert_eq!(started!=original,row["changed"].as_bool().unwrap());assert_eq!(turn.work,u128::from(row["work"].as_u64().unwrap()));let progress=turn.result.unwrap();assert_eq!(progress.copied_bytes,row["bytes"].as_u64().unwrap()as usize);assert!(progress.fits(grant));if started{let (repeated,performed)=with_effect(Default::default(),0,|effect|start_retained_close(&mut started,effect));assert_eq!(repeated.work,performed);assert_eq!(repeated.work,0);assert_eq!(repeated.result.unwrap(),Default::default());}}}
